8	//a basic transform hierarchy used in the following tests:
9	struct TestHierarchy {
10		//A is the parent of B is the parent of C.
11		std::shared_ptr< Transform > A, B, C;
12		TestHierarchy() {
13			A = std::make_shared< Transform >(
14				Vec3{1.0f, 0.0f, 0.0f}, //translate by (1,0,0)
15				Vec3{0.0f, 0.0f, 0.0f}, //no rotation
16				Vec3{2.0f, 2.0f, 2.0f}  //scale by 2x
17			);
18			B = std::make_shared< Transform >(
19				Vec3{0.0f, 1.0f, 0.0f}, //translate by (0,1,0)
20				Vec3{0.0f, 0.0f, 0.0f}, //no rotation
21				Vec3{2.0f, 2.0f, 2.0f}  //scale by 2x
22			);
23			C = std::make_shared< Transform >(
24				Vec3{0.0f, 0.0f, 1.0f}, //translate by (0,0,1)
25				Vec3{0.0f, 0.0f, 0.0f}, //no rotation
26				Vec3{2.0f, 2.0f, 2.0f}  //scale by 2x
27			);
28			B->parent = A;
29			C->parent = B;
30		}
31	};
32	
33	Test test_a1_task1_local_to_world_no_parent("a1.task1.local_to_world.no_parent", []() {
34		TestHierarchy hierarchy;
35	
36		Mat4 expected = hierarchy.A->local_to_parent();
37		Mat4 mat = hierarchy.A->local_to_world();
38	
39		if (Test::differs(mat, expected)) {
40			info("Transform A's local_to_world:");
41			Test::print_matrix(mat);
42			info("Transform A's local_to_parent:");
43			Test::print_matrix(expected);
44			throw Test::error("Transform without parent's local_to_world doesn't match local_to_parent.");
45		}
46	});
47	
48	Test test_a1_task1_world_to_local_no_parent("a1.task1.world_to_local.no_parent", []() {
49		TestHierarchy hierarchy;
50	
51		Mat4 expected = hierarchy.A->parent_to_local();
52		Mat4 mat = hierarchy.A->world_to_local();
53	
54		if (Test::differs(mat, expected)) {
55			info("Transform A's world_to_local:");
56			Test::print_matrix(mat);
57			info("Transform A's parent_to_local:");
58			Test::print_matrix(expected);
59			throw Test::error("Transform without parent's world_to_local doesn't match parent_to_local.");
60		}
61	});
