64	Test test_a1_task1_local_to_world("a1.task1.local_to_world", []() {
65		TestHierarchy hierarchy;
66	
67		Mat4 got = hierarchy.C->local_to_world();
68		Mat4 expected = Mat4{
69			8.0f, 0.0f, 0.0f, 0.0f,
70			0.0f, 8.0f, 0.0f, 0.0f,
71			0.0f, 0.0f, 8.0f, 0.0f,
72			1.0f, 2.0f, 4.0f, 1.0f
73		};
74	
75		if (Test::differs(got, expected)) {
76			info("Transform C's local_to_world:");
77			Test::print_matrix(got);
78			info("Expected:");
79			Test::print_matrix(expected);
80			throw Test::error("Transform's local_to_world doesn't match expected.");
81		}
82	});
