9	class Transform {
10	public:
11		Transform() = default;
12		Transform(Vec3 t, Vec3 euler, Vec3 s) : translation(t), rotation(Quat::euler(euler)), scale(s) {
13		}
14		Transform(Vec3 t, Quat q, Vec3 s) : translation(t), rotation(q), scale(s) {
15		}
16	
17		std::weak_ptr<Transform> parent;
18		Vec3 translation = Vec3{0.0f, 0.0f, 0.0f};
19		Quat rotation = Quat::euler(Vec3{0.0f, 0.0f, 0.0f});
20		Vec3 scale = Vec3{1.0f, 1.0f, 1.0f};
21	
22		Mat4 local_to_parent() const;
23		Mat4 parent_to_local() const;
24		Mat4 local_to_world() const;
25		Mat4 world_to_local() const;
26	
27		template< Intent I, typename F, typename T >
28		static void introspect(F&& f, T&& t) {
29			if constexpr (I != Intent::Animate) f("parent", t.parent);
30			f("translation", t.translation);
31			f("rotation", t.rotation);
32			f("scale", t.scale);
33		}
34		static inline const char *TYPE = "Transform";
35	};
36	
37	bool operator!=(const Transform& a, const Transform& b);
38

