2	#include "transform.h"
3	
4	Mat4 Transform::local_to_parent() const {
5		return Mat4::translate(translation) * rotation.to_mat() * Mat4::scale(scale);
6	}
7	
8	Mat4 Transform::parent_to_local() const {
9		return Mat4::scale(1.0f / scale) * rotation.inverse().to_mat() * Mat4::translate(-translation);
10	}
11	
12	Mat4 Transform::local_to_world() const {
13		// A1T1: local_to_world
14		//don't use Mat4::inverse() in your code.
15	
16		//walk up the parent chain, composing local_to_parent transforms:
17		// (points are column vectors, so the parent's transform goes on the left)
18		if (std::shared_ptr< Transform > parent_ = parent.lock()) {
19			return parent_->local_to_world() * local_to_parent();
20		}
21		//no parent means this transform's parent space *is* world space:
22		return local_to_parent();
23	}
24	
25	Mat4 Transform::world_to_local() const {
26		// A1T1: world_to_local
27		//don't use Mat4::inverse() in your code.
28	
29		//the inverse of local_to_world, so the factors appear in the opposite order
30		// and each one is inverted by the (exact) parent_to_local helper:
31		if (std::shared_ptr< Transform > parent_ = parent.lock()) {
32			return parent_to_local() * parent_->world_to_local();
33		}
34		//no parent means this transform's parent space *is* world space:
35		return parent_to_local();
36	}
37	
38	bool operator!=(const Transform& a, const Transform& b) {
39		return a.parent.lock() != b.parent.lock() || a.translation != b.translation ||
40		       a.rotation != b.rotation || a.scale != b.scale;
41	}
