443	inline Mat4 Mat4::angle_axis(float t, Vec3 axis) {
444		Mat4 ret;
445		float c = std::cos(Radians(t));
446		float s = std::sin(Radians(t));
447		axis.normalize();
448		Vec3 temp = axis * (1.0f - c);
449		ret[0][0] = c + temp[0] * axis[0];
450		ret[0][1] = temp[0] * axis[1] + s * axis[2];
451		ret[0][2] = temp[0] * axis[2] - s * axis[1];
452		ret[1][0] = temp[1] * axis[0] - s * axis[2];
453		ret[1][1] = c + temp[1] * axis[1];
454		ret[1][2] = temp[1] * axis[2] + s * axis[0];
455		ret[2][0] = temp[2] * axis[0] + s * axis[1];
456		ret[2][1] = temp[2] * axis[1] - s * axis[0];
457		ret[2][2] = c + temp[2] * axis[2];
458		return ret;
459	}
